def maximize_final_element():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    sequence = list(map(int, data[1:]))

    # Dynamic programming table to store the maximum values
    dp = [[0] * N for _ in range(N)]

    # Base case: single element is the element itself
    for i in range(N):
        dp[i][i] = sequence[i]

    # Fill the DP table
    for length in range(2, N + 1):  # length of the subarray
        for i in range(N - length + 1):
            j = i + length - 1
            if i == 0:
                dp[i][j] = max(dp[i + 1][j] + sequence[i], dp[i][j - 1])
            elif j == N - 1:
                dp[i][j] = max(dp[i][j - 1] + sequence[j], dp[i + 1][j])
            else:
                dp[i][j] = max(dp[i + 1][j] + sequence[i], dp[i][j - 1])

    # Reconstruct the sequence to find the operations
    i, j = 0, N - 1
    operations = []
    while i < j:
        if i == 0:
            if dp[i + 1][j] + sequence[i] > dp[i][j - 1]:
                operations.append(i + 1)
                j -= 1
            else:
                operations.append(j + 1)
                i += 1
        elif j == N - 1:
            if dp[i][j - 1] + sequence[j] > dp[i + 1][j]:
                operations.append(j + 1)
                i += 1
            else:
                operations.append(i + 1)
                j -= 1
        else:
            if dp[i + 1][j] + sequence[i] > dp[i][j - 1]:
                operations.append(i + 1)
                j -= 1
            else:
                operations.append(j + 1)
                i += 1

    # Output the maximum value and the operations
    print(dp[0][N - 1])
    print(len(operations))
    for op in operations:
        print(op)

