    while len(sequence) > 1:
        # Compute potential sums
        sums = []
        for i in range(1, len(sequence) - 1):
            sums.append((sequence[i - 1] + sequence[i + 1], i))

        if not sums:
            # If we are stuck and can only remove elements from the ends
            if len(sequence) > 2:
                if sequence[0] > sequence[-1]:
                    operations.append(1)
                    sequence.pop(0)
                else:
